import json
import time
from robot.api import logger
from taf.ue.rpc.mtk import mtk
from ute_common_abstract_core.message import Message, NotFoundKey
from ute_common_abstract_core.message_query import get_field_value
from taf.rfrl.utilities.robot.general import get_builtin_value, set_robot_suite_variable


class MissingMessage(Exception):
    """Exception for no messages in the flow."""
    pass


class MissingMessageParameter(Exception):
    """Exception for mismatching message parameters."""
    pass


class MissingMessageFlow(Exception):
    """Exception for no message flow. """
    pass


class mtk_messaging:

    def __init__(self):
        self._message_types = {
            '5GMM_REGISTRATION_COMPLETE': {'nas_5gs.mm.message_type': '0x43'},
            'VGSM_PDU_SESSION_ESTABLISHMENT_ACCEPT': {'nas_5gs.sm.message_type': '0xc2'},
            'NR_MEASUREMENT_REPORT': {'key': 'nr-rrc.measurementReport_element'},
            'NR_RRC_RELEASE': {'key': 'nr-rrc.rrcRelease_element'},
            'NR_RRC_RECONFIGURATION': {'key': 'nr-rrc.rrcReconfiguration_element'},
            'NR_RRC_RECONFIGURATION_COMPLETE': {'key': 'nr-rrc.rrcReconfigurationComplete_element'},
        }

        self._rpc_mtk_store = {}

    def setup_messaging(self, pyro_ip, pyro_port, ue_alias='UE_1'):
        """
        The method downloads messages form UE.
        :param ue_alias: any alias (it should be different for each UE)
        :param pyro_ip: ip address of pyro server
        :param pyro_port: pyro server port number
        :return: None
        """
        mtk_rpc = mtk()
        mtk_rpc.configure(pyro_ip, pyro_port)
        mtk_rpc.create_proxy('ota_json')
        self._rpc_mtk_store[ue_alias] = mtk_rpc

    def get_messages(self, messages_alias, ue_alias='UE_1', timeout=60):
        """
        The method gets ota messages.
        :param ue_alias: alias defined in 'Setup Messaging' keyword
        :param messages_alias: alias for list of new caught messages
        :param timeout: message downloading timeout
        :return: None
        """
        mtk_rpc = self._rpc_mtk_store.get(ue_alias, None)
        end_time = time.time() + timeout
        raw_ota_messages = []
        while time.time() < end_time:
            raw_ota_messages = mtk_rpc.read_latest_ota_message_details(proxy='ota_json')
            if raw_ota_messages:
                break
        messages = self._load_raw_ota_messages(raw_ota_messages)
        set_robot_suite_variable(messages_alias, messages)

    def expect_messages_in_flow(self, awaited_messages, messages_alias):
        """
        The method verify messages flow.
        :param awaited_messages: list of expected messages in flow (optionally with parameters), e.g.:
            [ NR_RRC_RECONFIGURATION(nr-rrc.physCellId=11), NR_RRC_RECONFIGURATION_COMPLETE(), ... ]
        :param messages_alias: alias for list of caught messages
        :return: None
        """
        messages = get_builtin_value(messages_alias)
        if not messages:
            raise MissingMessageFlow("No message flow. Please call 'Get Messages' keyword first.")
        awaited_messages_verified_result = self._prepare_initial_result_structure(awaited_messages)
        for awaited_message_index, awaited_message_verify in enumerate(awaited_messages_verified_result):
            if awaited_message_verify['message_occurred']:
                continue
            awaited_message_verified_index, awaited_message_verified_params = \
                self._search_awaited_message_in_occurred_messages(awaited_message_verify['awaited_message'], messages)
            if awaited_message_verified_index:
                awaited_messages_verified_result[awaited_message_index]['message_occurred'] = True
                awaited_messages_verified_result[awaited_message_index]['verified_parameters'] \
                    = awaited_message_verified_params[-1]
                messages = messages[awaited_message_verified_index[-1] + 1:]
        self._verify_result(awaited_messages_verified_result, messages_alias)

    def save_messages_to_file(self, messages_alias, filename=None):
        """
        The method saves messages to file.
        :param messages_alias: alias for list of caught messages
        :param filename: optional filename
        :return: None
        """
        messages = get_builtin_value(messages_alias)
        if not messages:
            raise MissingMessageFlow("Missing messages flow. Please call 'Get Messages' keyword first.")
        if filename is None:
            filename = messages_alias + '.json'
        filepath = get_builtin_value('OUTPUT_DIR') + '/' + filename
        with open(filepath, 'w') as fh:
            messages = [dict(timestamp=message.occurrence_time, content=message) for message in messages]
            messages = json.dumps(messages, indent=4)
            fh.write(messages)
        logger.info("Caught messages are saved in {} file.".format(filepath))

    def _search_awaited_message_in_occurred_messages(self, awaited_message, messages):
        """
        The method searches user-defined message in message flow occurred from UE.
        :param awaited_message: expected messages (defined by user), e.g.:
             NR_RRC_RECONFIGURATION(nr-rrc.physCellId=11)
        :param messages: list of caught messages
        :return: list of all messages matched by type, list of parameters for each message matched by type
        """
        awaited_message_verified_index = []
        awaited_message_verified_params = []
        for index, message in enumerate(messages):
            parsed_awaited_message = self._parse_awaited_message(awaited_message)
            if self._verify_existence_of_message(parsed_awaited_message[0], message):
                query = self._verify_message_parameters(parsed_awaited_message[1], message)
                awaited_message_verified_params.append(query)
                awaited_message_verified_index.append(index)
                if len(query) == 0 or all(query):
                    break
        return awaited_message_verified_index, awaited_message_verified_params

    def _load_raw_ota_messages(self, raw_messages):
        """
        The function creates list of Message objects.
        :param raw_messages: list of received messages, e.g.:
            [ "2021-01-20 13:08:53.167000  {\"nr-rrc\": \
              {\"nr-rrc.UL_DCCH_Message_element\": {\"per.choice_index": \"0\",\"nr-rrc.message\": \"0\", ... }}}",
              ...
            ]
        :type raw_messages: list of str
        :return: list of parsed messages, e.g.:
            [ Message(occurrence_time=2021-02-18 10:36:33.408000;{'nr-rrc':
              {'nr-rrc.UL_DCCH_Message_element': {'per.choice_index': '0','nr-rrc.message': '0', ... }}}), ... ]
        """
        messages = []
        for message in raw_messages:
            start_message_bracket = message.index('{')
            timestamp = message[:start_message_bracket - 2]
            json_message = json.loads(message[start_message_bracket:])
            messages.append(Message(json_message, {'occurrence_time': timestamp}))
        return messages

    def _parse_awaited_message(self, message):
        """
        The function parses message with parameters defined by user.
        :param message: message defined by user, e.g.:
            [ NR_RRC_RECONFIGURATION(nr-rrc.physCellId=11), NR_RRC_RECONFIGURATION_COMPLETE(), ... ]
        :return: tuple consisting of message type and message parameters
        """
        parameters = []
        try:
            message_type, raw_parameters = message.rstrip(")").split("(")
            if raw_parameters:
                for parameter in raw_parameters.split(","):
                    parameters.append(tuple(parameter.split('=')))
        except ValueError:
            message_type = message
        return message_type, parameters

    def _verify_message_parameters(self, message_parameters_to_verify, message):
        """
        The method checks if user-defined message parameters are contained in the caught message from the UE.
        :param message_parameters_to_verify: list of message parameters
        :param message: caught message
        :return: list with bool indicators of matching for each parameter
            (the order of indicators and parameters in both lists is consistent)
        """
        verification_result = []
        for parameter in message_parameters_to_verify:
            try:
                if len(parameter) == 1:
                    parameter_is_proper = bool(get_field_value(message=message, field_selector=parameter[0]))
                else:
                    parameter_value = get_field_value(message=message, field_selector=parameter[0])
                    parameter_is_proper = parameter_value == parameter[1] or parameter[1] in parameter_value
            except NotFoundKey:
                parameter_is_proper = False
            verification_result.append(parameter_is_proper)
        return verification_result

    def _verify_existence_of_message(self, message_name, message):
        """
        The method verifies caught message.
        :param message_name: name of message according to _message_types collection e.g.: 'NR_RRC_RECONFIGURATION'
        :param message: caught message
        :return: True if message was matched, otherwise False
        """
        try:
            if 'key' in self._message_types[message_name]:
                message_type = get_field_value(message=message,
                                               field_selector=self._message_types[message_name]['key'])
                verification_result = bool(message_type)
            else:
                message_key = list(self._message_types[message_name].keys())[0]
                message_type = get_field_value(message=message, field_selector=message_key)
                verification_result = message_type == self._message_types[message_name][message_key]
        except NotFoundKey:
            verification_result = False
        return verification_result

    def _prepare_initial_result_structure(self, awaited_messages):
        """
        The method prepares initial result structure, which will be fill during message verification procedure.
        :param awaited_messages: list of expected messages in flow (optionally with parameters), e.g.:
            [ NR_RRC_RECONFIGURATION(nr-rrc.physCellId=11), NR_RRC_RECONFIGURATION_COMPLETE(), ... ]
        :return:
        """
        awaited_messages_verified_result = []
        for msg in awaited_messages:
            awaited_messages_verified_result.append({'awaited_message': msg,
                                                     'message_occurred': False,
                                                     'verified_parameters': []})
        return awaited_messages_verified_result

    def _verify_result(self, result, message_alias):
        """
        The method analyses result of message verification procedure until the first discrepancy occurs.
        :param result: result of message verification procedure
        :param message_alias: alias for list of caught messages
        :return: None
        """
        for message_result in result:
            if not message_result['message_occurred']:
                self._verify_no_missing_message_error_found(message_result, message_alias)
            if not all(message_result['verified_parameters']):
                self._verify_no_missing_message_parameter_errors_found(message_result, message_alias)

    def _verify_no_missing_message_error_found(self, message_result, message_alias):
        """
        The method will log and throw an exception when there is no awaited message in the flow.
        :param message_result: result of message verification procedure
        :param message_alias: alias for list of caught messages
        :return: None
        """
        err_msg = "{} message did not occur (no message in flow).".format(message_result['awaited_message'])
        logger.error(err_msg)
        self.save_messages_to_file(message_alias)
        raise MissingMessage(err_msg)

    def _verify_no_missing_message_parameter_errors_found(self, message_result, message_alias):
        """
        The method will log and throw an exception in the case of a missing parameter or an incorrect parameter value.
        :param message_result: result of message verification procedure
        :param message_alias: alias for list of caught messages
        :return: None
        """
        parsed_awaited_message = self._parse_awaited_message(message_result['awaited_message'])
        err_msg = msg = "{} message occurred, but parameters are invalid.".format(
            message_result['awaited_message'])
        msg += ':\n'
        for i, parameter_result in enumerate(message_result['verified_parameters']):
            if len(parsed_awaited_message[1][i]) == 1:
                msg += 'parameter:  {}     {}\n'.format(parsed_awaited_message[1][i][0], parameter_result)
            else:
                msg += 'parameter:  {}={}  {}\n'.format(parsed_awaited_message[1][i][0],
                                                        parsed_awaited_message[1][i][1], parameter_result)
        logger.error(msg)
        self.save_messages_to_file(message_alias)
        raise MissingMessageParameter(err_msg)
